#include "memory_collections.hpp"
#include <iostream>
#include <stdexcept>
int main(){try{mycelia::DynamicAssociativeDatabase db;mycelia::sql::Row memory;memory["title"]=std::string("Build diagnosis");auto id=db.store_sql_record("manual_memory",memory);auto project=krmemory::create_collection(db,"KR Compiler IDE","project");auto target=krmemory::create_collection(db,"KR Mycelia","project");krmemory::assign_to_collection(db,id,project);if(!krmemory::rename_collection(db,project,"KR Compiler IDE archive"))throw std::runtime_error("collection rename failed");if(krmemory::merge_collections(db,project,target)!=1||krmemory::collection_members(db,target).size()!=1)throw std::runtime_error("collection merge failed");if(!krmemory::delete_collection(db,project)||krmemory::delete_collection(db,project))throw std::runtime_error("collection delete failed");std::cout<<"PASS: DAD collection lifecycle and belongs_to relationship\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
